INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Arbeitspakete und Meilensteine nur für große Projekte wichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte brauchen Struktur"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Definition von Arbeitspaketen und Meilensteinen?', 3, '[{"text": "Projektstrukturierung", "correct": true, "because": "Aufgaben und Etappen klar definieren"}, {"text": "Datenmenge maximieren", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Organisation im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu Arbeitspaketen und Meilensteinen?', 5, '[{"text": "Arbeitspakete", "correct": true, "because": "Kleinste Arbeitseinheiten"}, {"text": "Meilensteine", "correct": true, "because": "Markieren wichtige Etappen"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Strukturfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Arbeitspakete und Meilensteine fördern Transparenz. b) Sie sind nur für den Projektstart nötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Durchgehend relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Definition von Arbeitspaketen und Meilensteinen?', 4, '[{"text": "Aufgabenaufteilung", "correct": false, "because": "Kern der Arbeitspakete"}, {"text": "Zeitliche Markierungen", "correct": false, "because": "Meilensteine definieren"}, {"text": "Visuelles Design", "correct": true, "because": "Kein Strukturfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Arbeitspakete und Meilensteine die Fortschrittskontrolle unterstützen?', 2, '[{"text": "Ja", "correct": true, "because": "Zeigen Projektstatus"}, {"text": "Nein", "correct": false, "because": "Teil der Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist typisch für Arbeitspakete?', 3, '[{"text": "Aufgabenbeschreibung", "correct": true, "because": "Definiert konkrete Arbeit"}, {"text": "Hohe Serverleistung", "correct": false, "because": "Irrelevant"}, {"text": "Statische IPs", "correct": false, "because": "Kein Strukturfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bestandteile gehören zur Definition von Arbeitspaketen und Meilensteinen?', 5, '[{"text": "Lieferergebnisse", "correct": true, "because": "Arbeitspakete liefern Ergebnisse"}, {"text": "Fristen", "correct": true, "because": "Meilensteine setzen Zeitpunkte"}, {"text": "Maximale Speichergröße", "correct": false, "because": "Nicht relevant"}, {"text": "Animationseffekte", "correct": false, "because": "Kein Strukturfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Arbeitspakete und Meilensteine helfen bei der Planung. b) Sie sind nur für komplexe Projekte nötig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch einfache Projekte profitieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Definition von Arbeitspaketen und Meilensteinen?', 4, '[{"text": "Aufgabenaufteilung", "correct": false, "because": "Kern der Arbeitspakete"}, {"text": "Meilensteinziele", "correct": false, "because": "Definiert Etappen"}, {"text": "Grafisches Design", "correct": true, "because": "Kein Strukturfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Arbeitspakete und Meilensteine nur für den Projektstart?', 2, '[{"text": "Nein", "correct": true, "because": "Durchgehend relevant"}, {"text": "Ja", "correct": false, "because": "Kontinuierliche Steuerung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden unterstützen die Definition von Arbeitspaketen und Meilensteinen?', 4, '[{"text": "Work Breakdown Structure", "correct": true, "because": "Zerlegt Projekt"}, {"text": "Meilensteinplan", "correct": true, "because": "Setzt Zeitpunkte"}, {"text": "Visuelles Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Arbeitspakete und Meilensteine unnötig sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Fördern Struktur und Kontrolle"}, {"text": "Ja", "correct": false, "because": "Wichtig für Planung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Definition von Arbeitspaketen und Meilensteinen?', 3, '[{"text": "Klarheit der Aufgaben", "correct": true, "because": "Fördert Verständnis"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Gründlichkeit zählt"}, {"text": "Schriftgröße", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Meilensteine markieren Fortschritt. b) Arbeitspakete sind nur für große Teams.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch kleine Teams nutzen sie"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Arbeitspakete und Meilensteine?', 5, '[{"text": "Projektübersicht", "correct": true, "because": "Klarheit schaffen"}, {"text": "Fortschrittskontrolle", "correct": true, "because": "Zeigt Status"}, {"text": "Maximale Speichergröße", "correct": false, "because": "Nicht relevant"}, {"text": "Animationseffekte", "correct": false, "because": "Kein Strukturfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Definition von Arbeitspaketen und Meilensteinen unwichtig?', 3, '[{"text": "Aufgabenbeschreibung", "correct": false, "because": "Definiert Arbeit"}, {"text": "Meilensteinfristen", "correct": false, "because": "Setzt Zeitpunkte"}, {"text": "Schriftgröße", "correct": true, "because": "Kein Strukturfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Arbeitspakete und Meilensteine nur für technische Projekte?', 3, '[{"text": "Nein", "correct": true, "because": "Für alle Projektarten nützlich"}, {"text": "Ja", "correct": false, "because": "Universell anwendbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Arbeitspakete und Meilensteine regelmäßig überprüft werden sollten?', 2, '[{"text": "Ja", "correct": true, "because": "Anpassung an Änderungen"}, {"text": "Nein", "correct": false, "because": "Flexibilität nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug wähle ich für die Definition von Arbeitspaketen und Meilensteinen?', 4, '[{"text": "Work Breakdown Structure", "correct": true, "because": "Zerlegt Projekt in Aufgaben"}, {"text": "Zufällige Daten", "correct": false, "because": "Irrelevant"}, {"text": "Grafisches Design", "correct": false, "because": "Kein Strukturfokus"}]');
